77	/// Options passed from TypeScript — flat struct for easy NAPI marshalling.
78	#[napi(object)]
79	pub struct JsExtractOptions {
80	    pub src_dirs: Vec<String>,
81	    pub exclude: Option<Vec<String>>,
82	    #[napi(ts_type = "'react18' | 'react19'")]
83	    pub react_version: Option<String>,
84	    pub cross_package: Option<bool>,
85	    pub pandacss_outdir: Option<String>,
86	    pub variant_functions: Option<Vec<String>>,
87	    #[napi(ts_type = "'curated' | 'full' | 'none'")]
88	    pub html_attributes: Option<String>,
89	    pub tsconfig_path: Option<String>,
90	    pub extra_builtins: Option<Vec<String>>,
91	    pub vanilla_extract: Option<bool>,
92	    pub cache_dir: Option<String>,
93	    pub resolve_complex_types: Option<bool>,
94	    // Complex fields accepted as JSON strings to avoid napi object complexity:
95	    /// JSON: Record<string, string[]>
96	    pub extra_paths_json: Option<String>,
97	    /// JSON: Record<string, {kind: ...}>
98	    pub known_type_overrides_json: Option<String>,
99	}
