167	/// Cold extraction — returns JSON string of ExtractionOutput.
168	/// Use for: build-time extraction, CLI backing, one-off runs.
169	#[napi]
170	pub async fn extract_all(options: JsExtractOptions) -> napi::Result<String> {
171	    let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
172	    tokio::task::spawn_blocking(move || {
173	        match oxc_react_docgen_core::panic_guard::contain_panic("extract_all", move || {
174	            #[cfg(test)]
175	            if pipeline_options.src_dirs.iter().any(|d| d.as_str() == EXTRACT_ALL_PANIC_TEST_SENTINEL) {
176	                panic!("simulated extract_all panic (test-only sentinel)");
177	            }
178	
179	            let output = oxc_react_docgen_core::pipeline::extract(&pipeline_options);
180	            extraction_output_to_json(&output).map_err(|e| napi::Error::from_reason(e.to_string()))
181	        }) {
182	            Ok(result) => result,
183	            Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
184	        }
185	    })
186	    .await
187	    .map_err(|e| napi::Error::from_reason(e.to_string()))?
188	}
