212	/// Incremental extraction for a single changed file.
213	/// Returns JSON string of IncrementalUpdate.
214	/// Use for: Vite HMR hotUpdate.
215	#[napi]
216	pub async fn extract_file_incremental(
217	    file_path: String,
218	    session_id: u32,
219	    options: JsExtractOptions,
220	) -> napi::Result<String> {
221	    tokio::task::spawn_blocking(move || {
222	        match oxc_react_docgen_core::panic_guard::contain_panic("extract_file_incremental", move || {
223	            let session = match SESSIONS.get(&session_id) {
224	                Some(s) => s.clone(),
225	                None => {
226	                    #[cfg(test)]
227	                    if session_id == AUTO_VIVIFY_PANIC_TEST_SENTINEL {
228	                        panic!("simulated extract_file_incremental auto-vivification panic (test-only sentinel)");
229	                    }
230	
231	                    let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
232	                    let s = Arc::new(WatchSession::new(pipeline_options));
233	                    SESSIONS.insert(session_id, s.clone());
234	                    s
235	                }
236	            };
237	
238	            #[cfg(test)]
239	            if file_path == EXTRACT_FILE_INCREMENTAL_PANIC_TEST_SENTINEL {
240	                panic!("simulated extract_file_incremental core-call panic (test-only sentinel)");
241	            }
242	
243	            let path = Utf8Path::new(&file_path);
244	            let update = session.update_file(path);
245	            incremental_update_to_json(&update).map_err(|e| napi::Error::from_reason(e.to_string()))
246	        }) {
247	            Ok(result) => result,
248	            Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
249	        }
250	    })
251	    .await
252	    .map_err(|e| napi::Error::from_reason(e.to_string()))?
253	}
