11	pub(super) fn resolve_template_literal(
12	    parts: &[CollectedType],
13	    consuming_file: &Utf8Path,
14	    ctx: &ResolutionContext,
15	    state: &mut ResolveState,
16	    depth: u8,
17	) -> PropType {
18	    // Try to expand: `compact-${Size}` where Size = "xs"|"sm"|...
19	    // Each part must be either a string literal or a type that resolves to a LiteralUnion.
20	    let expanded = try_expand_template_literal(parts, consuming_file, ctx, state, depth);
21	
22	    if let Some(values) = expanded {
23	        if let [only] = values.as_slice() {
24	            return PropType::StringLiteral(only.clone());
25	        }
26	        return PropType::LiteralUnion { members: values, has_default: false };
27	    }
28	
29	    let raw = CollectedType::TemplateLiteral(parts.to_vec()).to_raw_string();
30	    let diagnostic = Diagnostic {
31	        severity: DiagnosticSeverity::Info,
32	        message: format!("Template literal type '{}' could not be statically expanded", raw),
33	        file: Some(consuming_file.to_string()),
34	        line: None,
35	        column: None,
36	        help: Some("Enable typescript-go or add explicit string literal union for template literal types.".into()),
37	        code: DiagnosticCode::TemplateLiteralOpaque,
