42	/// Cap on the Cartesian product `try_expand_template_literal` accumulates
43	/// across a template literal's parts. Each part can itself be a union with
44	/// many members, so the product is exponential in part count — an attacker-
45	/// or generator-controlled type with enough parts/members would otherwise
46	/// allocate unboundedly before ever returning. Same shape of guard as
47	/// `extractor/mod.rs`'s `MAX_SOURCE_NESTING_DEPTH`, applied to a different
48	/// input-derived size.
49	const MAX_TEMPLATE_LITERAL_EXPANSIONS: usize = 4096;
50	
51	/// Try to fully expand a template literal into a list of concrete string values.
52	/// Returns `None` if any part cannot be resolved to string literals.
53	pub(super) fn try_expand_template_literal(
54	    parts: &[CollectedType],
55	    consuming_file: &Utf8Path,
56	    ctx: &ResolutionContext,
57	    state: &mut ResolveState,
58	    depth: u8,
59	) -> Option<Vec<String>> {
60	    // Collect per-part string alternatives.
61	    let mut per_part: Vec<Vec<String>> = Vec::new();
62	
63	    for part in parts {
64	        match part {
65	            CollectedType::StringLiteral(s) => {
66	                per_part.push(vec![s.to_string()]);
67	            }
68	            CollectedType::Named { name, .. } => {
69	                // Look up in global type aliases for a LiteralUnion.
70	                let resolved = resolve_named_to_string_literals(name.as_str(), consuming_file, ctx, state, depth + 1);
71	                if let Some(strs) = resolved {
72	                    per_part.push(strs);
73	                } else {
74	                    return None; // Can't expand.
75	                }
76	            }
77	            _ => {
78	                let pt = resolve_collected_type(part, consuming_file, ctx, state, depth + 1);
79	                match &pt {
80	                    PropType::StringLiteral(s) => per_part.push(vec![s.clone()]),
81	                    PropType::LiteralUnion { members, .. } => per_part.push(members.clone()),
82	                    PropType::Union(members) => {
83	                        let strs: Option<Vec<String>> = members
84	                            .iter()
85	                            .map(|m| if let PropType::StringLiteral(s) = m { Some(s.clone()) } else { None })
86	                            .collect();
87	                        if let Some(s) = strs {
88	                            per_part.push(s);
89	                        } else {
90	                            return None;
91	                        }
92	                    }
93	                    _ => return None,
94	                }
95	            }
96	        }
97	    }
98	
99	    if per_part.is_empty() {
100	        return Some(vec![String::new()]);
101	    }
102	
103	    // Cartesian product across all parts.
104	    let mut result = vec![String::new()];
105	    for alternatives in per_part {
106	        if result.len().saturating_mul(alternatives.len()) > MAX_TEMPLATE_LITERAL_EXPANSIONS {
107	            return None; // Falls through to the Opaque+diagnostic degrade path in resolve_template_literal.
108	        }
109	        let mut next = Vec::with_capacity(result.len() * alternatives.len());
110	        for prefix in &result {
111	            for alt in &alternatives {
112	                next.push(format!("{}{}", prefix, alt));
113	            }
114	        }
115	        result = next;
116	    }
117	
118	    Some(result)
119	}
