// nested positions in one fixture rather than leaving them unasserted.

#[test]
fn nan_number_literal_survives_the_round_trip_when_nested() {
    let original = PropType::Union(vec![
        PropType::Array(Box::new(PropType::NumberLiteral(f64::NAN))),
        PropType::Tuple(vec![PropType::NumberLiteral(f64::NAN), PropType::String]),
        PropType::Object(vec![ObjectField {
            name: "n".into(),
            prop_type: PropType::NumberLiteral(f64::NAN),
            required: true,
            description: String::new(),
        }]),
        PropType::Named { name: "Foo".into(), args: vec![PropType::NumberLiteral(f64::NAN)] },
    ]);

    let json = serde_json::to_value(&original).expect("serialize");
    let restored: PropType = serde_json::from_value(json).expect("deserialize");

    let PropType::Union(members) = &restored else { panic!("expected Union, got {restored:?}") };

    let PropType::Array(inner) = &members[0] else { panic!("expected Array, got {:?}", members[0]) };
    assert!(matches!(**inner, PropType::NumberLiteral(n) if n.is_nan()), "NaN nested in Array did not survive, got {inner:?}");

    let PropType::Tuple(items) = &members[1] else { panic!("expected Tuple, got {:?}", members[1]) };
    assert!(matches!(items[0], PropType::NumberLiteral(n) if n.is_nan()), "NaN nested in Tuple did not survive, got {:?}", items[0]);

    let PropType::Object(fields) = &members[2] else { panic!("expected Object, got {:?}", members[2]) };
    assert!(
        matches!(fields[0].prop_type, PropType::NumberLiteral(n) if n.is_nan()),
        "NaN nested in Object's ObjectField.prop_type did not survive, got {:?}",
        fields[0].prop_type
    );

    let PropType::Named { args, .. } = &members[3] else { panic!("expected Named, got {:?}", members[3]) };
    assert!(matches!(args[0], PropType::NumberLiteral(n) if n.is_nan()), "NaN nested in Named's args did not survive, got {:?}", args[0]);
}

