41	/// Stateful session for incremental watch-mode extraction.
42	///
43	/// `global`, `reverse_deps`, and `component_cache` are updated atomically /
44	/// concurrently on each file change. `reverse_deps` is rebuilt in full on
45	/// structural changes (new file, deleted file) via a new `WatchSession` — it
46	/// does not track incremental import-graph edits within a session.
47	pub struct WatchSession {
48	    pub options: PipelineOptions,
49	    /// Current merged source data — swapped atomically via `ArcSwap`.
50	    pub global: ArcSwap<GlobalSourceData>,
51	    /// Reverse-dependency graph built at initialisation time — swapped
52	    /// atomically via `ArcSwap` so `initialize()` can populate it from the
53	    /// first fully-merged `global` (it doesn't exist yet at `new()`).
54	    pub reverse_deps: ArcSwap<ReverseDeps>,
55	    /// Per-file SourceData cache (avoids re-reading files that haven't changed).
56	    pub source_cache: DashMap<Utf8PathBuf, SourceData>,
57	    /// Latest resolved component entries, keyed by display name.
58	    pub component_cache: DashMap<String, ComponentEntry>,
59	    /// Latest diagnostics per file, replaced (not appended) on each re-update so a
60	    /// fixed file's stale diagnostics don't linger — mirrors GlobalSourceData::remove_file's
61	    /// per-file replacement semantics.
62	    pub diagnostics: DashMap<Utf8PathBuf, Vec<Diagnostic>>,
63	    /// TypeScript's own lib.d.ts paths, computed once here at `initialize()`
64	    /// rather than by every `ResolutionContext::new` inside `update_file` —
65	    /// `options.src_dirs` (the only input this depends on) never changes
66	    /// within a session, so re-walking the filesystem for it on every single
67	    /// file save would be pure waste.
68	    ambient_global_files: std::sync::OnceLock<Vec<Utf8PathBuf>>,
69	    /// Guards initialize() so concurrent callers don't race to build caches.
70	    initialized: Mutex<bool>,
71	}
72	
73	impl WatchSession {
74	    /// Create an empty WatchSession (call `initialize()` before first use).
75	    pub fn new(options: PipelineOptions) -> Self {
76	        Self {
77	            options,
78	            global: ArcSwap::new(Arc::new(GlobalSourceData::default())),
79	            reverse_deps: ArcSwap::new(Arc::new(ReverseDeps { inner: Default::default() })),
80	            source_cache: DashMap::new(),
81	            component_cache: DashMap::new(),
82	            diagnostics: DashMap::new(),
83	            ambient_global_files: std::sync::OnceLock::new(),
84	            initialized: Mutex::new(false),
85	        }
86	    }
87	
88	    /// Run a full cold extraction to populate this session's caches.
89	    ///
90	    /// Idempotent — concurrent or repeated calls return the existing snapshot
91	    /// without re-running extraction.
92	    pub fn initialize(&self) -> ExtractionOutput {
93	        let mut guard = self.initialized.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
94	        if *guard {
95	            return self.snapshot();
96	        }
97	
98	        // Single real pipeline run (discover, parse, merge, Full-mode
