        for i in 0..(MAX_CACHE_ENTRIES + 10) {
            let key = CacheKey { path: Utf8PathBuf::from(format!("file_{i}.d.ts")), size: 10, mtime_ns: 100 };
            cache.store.insert(key, SourceData::default());
        }

